// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;

/// Test contract for the hover values of the step debugger.
contract HoverProbe {
    enum Mode { Off, On, Auto }
    struct Pair { uint128 a; uint128 b; }

    uint256 public total;
    mapping(address => uint256) internal credits;

    function run(
        address who,
        int64 delta,
        bool flag,
        bytes4 tag,
        Mode mode,
        string calldata label,
        uint256[] calldata xs
    ) external returns (uint256 sum, bytes32 digest) {
        sum = _mix(who, delta, flag, tag, mode);
        string memory copy = label;
        digest = _hash(copy, xs.length, Pair(1, 2));
        uint256[] memory ys = new uint256[](xs.length);
        for (uint256 i = 0; i < xs.length; i++) ys[i] = xs[i];
        sum += _sum(ys, 0);
        _credit(credits, who, sum);
        total = sum;
    }

    function _mix(address who, int64 delta, bool flag, bytes4 tag, Mode mode)
        internal
        view
        returns (uint256 out)
    {
        out = uint160(who) % 7;
        if (flag) out += 1;
        if (delta < 0) out += uint64(-delta);
        out += uint32(tag) % 5 + uint8(mode) + total;
    }

    function _hash(string memory text, uint256 n, Pair memory p) internal pure returns (bytes32 h) {
        h = keccak256(abi.encodePacked(text, n, p.a));
    }

    function _sum(uint256[] memory ys, uint256 i) internal pure returns (uint256 acc) {
        if (i == ys.length) return 0;
        acc = ys[i] + _sum(ys, i + 1);
    }

    function _credit(mapping(address => uint256) storage book, address who, uint256 amount) internal {
        book[who] += amount;
    }

    function bump(uint256 amount) external returns (uint256) {
        amount = amount + 1;
        (uint256 twice, ) = _twice(amount, "x2");
        total = twice;
        return twice;
    }

    function _twice(uint256 value, bytes memory memo) internal pure returns (uint256 result, uint256) {
        result = value * 2 + memo.length;
        return (result, 0);
    }

    function fail(uint256 code, string calldata why) external view {
        _check(code, why, total);
    }

    function _check(uint256 code, string memory why, uint256 seen) internal pure {
        if (seen > 1000) code += 1;
        require(code == 0, why);
    }

    function shadow(uint256 amount) external pure returns (uint256 r) {
        r = amount;
        {
            uint256 amount = 7;
            r += amount;
        }
    }
}

