// SPDX-License-Identifier: MIT
pragma solidity ^0.8.17;
contract Small {
    uint256 public last;
    function f(uint256 a, uint256 b) external returns (uint256 r) {
        r = _g(a, b);
        last = r;
    }
    function _g(uint256 x, uint256 y) internal pure returns (uint256 z) {
        z = x - y;
    }
}

